using Xunit;

namespace Goldpath.Cli.Tests;

/// <summary>
/// Mutation-killing companions to <see cref="AddWorkerTests"/>: every generated byte, every
/// refusal message and every process invocation is asserted EXACTLY — a skeleton that is
/// "almost right" compiles into an app that refuses to start (the launchSettings lesson).
/// </summary>
public class AddWorkerMutationTests
{
    private sealed record Result(int Code, string Output, string Error);

    private static Result Add(FakeApp app, IProcessRunner runner, string name, string trigger)
        => Add(app.Root, runner, name, trigger);

    private static Result Add(string root, IProcessRunner runner, string name, string trigger)
    {
        var output = new StringWriter();
        var error = new StringWriter();
        var code = CliRunner.Run(["add", "worker", name, "--trigger", trigger, "--path", root], runner, output, error);
        return new Result(code, output.ToString(), error.ToString());
    }

    private static string Line(string text) => text + Environment.NewLine;

    private static string Normalize(string text) => text.Replace("\r\n", "\n", StringComparison.Ordinal);

    private static string ProjectDir(FakeApp app, string projectName) => Path.Combine(app.Root, "src", projectName);

    // ── refusals: message + exit code, nothing written ──────────────────────────────────

    [Fact]
    public void Unknown_trigger_lists_the_accepted_ones()
    {
        using var app = new FakeApp();
        var result = Add(app, new FakeProcessRunner(), "payments", "cron");
        Assert.Equal(2, result.Code);
        Assert.Equal(Line("goldpath: unknown trigger 'cron' — one of: queue, schedule, jobs"), result.Error);
    }

    [Fact]
    public void A_directory_without_a_manifest_is_refused_with_the_path()
    {
        var bare = Path.Combine(Path.GetTempPath(), $"goldpath-cli-bare-{Guid.NewGuid():N}");
        Directory.CreateDirectory(bare);
        try
        {
            var result = Add(bare, new FakeProcessRunner(), "payments", "schedule");
            Assert.Equal(1, result.Code);
            var manifest = Path.Combine(bare, ".goldpath", "manifest.yaml");
            Assert.Equal(Line($"goldpath: no manifest at {manifest} — goldpath add runs inside a Goldpath-generated app (or pass --path)."), result.Error);
        }
        finally
        {
            Directory.Delete(bare, recursive: true);
        }
    }

    [Fact]
    public void A_worker_manifest_is_refused_by_its_kind()
    {
        using var app = new FakeApp(kind: "worker");
        var result = Add(app, new FakeProcessRunner(), "payments", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: this manifest is kind 'worker' — workers join a SOLUTION's AppHost; run goldpath add there."), result.Error);
    }

    [Fact]
    public void A_manifest_without_a_kind_is_reported_as_none()
    {
        using var app = new FakeApp();
        var lines = File.ReadAllLines(app.Manifest).Where(line => !line.StartsWith("kind:", StringComparison.Ordinal));
        File.WriteAllLines(app.Manifest, lines);

        var result = Add(app, new FakeProcessRunner(), "payments", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: this manifest is kind '<none>' — workers join a SOLUTION's AppHost; run goldpath add there."), result.Error);
    }

    [Fact]
    public void A_queue_worker_without_messaging_teaches_the_broker_seam()
    {
        using var app = new FakeApp();
        var result = Add(app, new FakeProcessRunner(), "payments", "queue");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: a queue worker consumes from the broker — no AddGoldpathMessaging(...) found in the composition root. Wire messaging first (a broker resource + the AddGoldpathMessaging block), then re-run."), result.Error);
    }

    private static void DropConnectionString(FakeApp app)
        => File.WriteAllText(app.Program, app.Read(app.Program).Replace("var shopDbConnection = builder.Configuration.GetConnectionString(\"shopdb\");", string.Empty, StringComparison.Ordinal));

    [Theory]
    [InlineData("queue")]
    [InlineData("jobs")]
    public void A_persisting_worker_without_a_connection_name_is_refused(string trigger)
    {
        using var app = new FakeApp(messagingWired: true);
        DropConnectionString(app);
        var result = Add(app, new FakeProcessRunner(), "payments", trigger);
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: no GetConnectionString(...) found in the composition root — this worker persists into the app database and needs its connection name."), result.Error);
        Assert.False(Directory.Exists(ProjectDir(app, "Shop.PaymentsWorker")));
    }

    [Fact]
    public void A_schedule_worker_needs_no_connection_name()
    {
        using var app = new FakeApp();
        DropConnectionString(app);
        var result = Add(app, new FakeProcessRunner(), "cleanup", "schedule");
        Assert.Equal(0, result.Code);
        Assert.Equal(string.Empty, result.Error);
    }

    [Fact]
    public void An_existing_project_directory_is_refused_by_name()
    {
        using var app = new FakeApp();
        Directory.CreateDirectory(ProjectDir(app, "Shop.CleanupWorker"));
        var result = Add(app, new FakeProcessRunner(), "cleanup", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: src/Shop.CleanupWorker already exists — pick another name or remove it first."), result.Error);
    }

    [Fact]
    public void A_missing_solution_file_is_refused_before_anything_is_written()
    {
        using var app = new FakeApp();
        var appHostBefore = app.Read(app.AppHost);
        File.Delete(Path.Combine(app.Root, "Shop.sln"));
        var result = Add(app, new FakeProcessRunner(), "cleanup", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: no .sln at the app root — goldpath add worker wires the project into the solution."), result.Error);
        Assert.False(Directory.Exists(ProjectDir(app, "Shop.CleanupWorker")));
        Assert.Equal(appHostBefore, app.Read(app.AppHost));
    }

    [Fact]
    public void Two_solution_files_are_refused_with_the_count()
    {
        using var app = new FakeApp();
        File.WriteAllText(Path.Combine(app.Root, "Other.sln"), "");
        var result = Add(app, new FakeProcessRunner(), "cleanup", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: 2 .sln files at the app root — goldpath cannot choose; keep exactly one."), result.Error);
    }

    [Fact]
    public void A_name_without_letters_is_a_usage_error()
    {
        using var app = new FakeApp();
        var result = Add(app, new FakeProcessRunner(), "---", "schedule");
        Assert.Equal(2, result.Code);
        Assert.Equal(Line("goldpath: '---' does not yield a project name — use letters (e.g. payments, eod-report)."), result.Error);
        Assert.DoesNotContain(Directory.GetDirectories(Path.Combine(app.Root, "src")), d => d.EndsWith("Worker", StringComparison.Ordinal));
    }

    // ── the process seam: exact invocations, exact rollback ────────────────────────────

    [Fact]
    public void The_solution_entry_is_the_exact_dotnet_sln_add_call()
    {
        using var app = new FakeApp();
        // A second top-level file: only the *.sln pattern must find the solution.
        File.WriteAllText(Path.Combine(app.Root, "README.md"), "# Shop");
        var runner = new FakeProcessRunner();
        Assert.Equal(0, Add(app, runner, "cleanup", "schedule").Code);

        var sln = runner.Calls[0];
        Assert.Equal("dotnet", sln.FileName);
        Assert.Equal(
            ["sln", Path.Combine(app.Root, "Shop.sln"), "add", Path.Combine(app.Root, "src", "Shop.CleanupWorker", "Shop.CleanupWorker.csproj")],
            sln.Arguments);
        Assert.Equal(app.Root, sln.WorkingDirectory);

        // Then the engine, in order: validate, drift — both with the app root as CWD.
        Assert.Equal(3, runner.Calls.Count);
        Assert.Contains("validate", runner.Calls[1].Arguments);
        Assert.Equal(["drift", "--repo", "."], runner.Calls[2].Arguments.TakeLast(3));
        Assert.Equal(app.Root, runner.Calls[2].WorkingDirectory);
    }

    [Fact]
    public void A_failed_sln_add_restores_everything_and_says_so()
    {
        using var app = new FakeApp();
        var appHostBefore = app.Read(app.AppHost);
        var appHostProjectBefore = app.Read(app.AppHostProject);
        var runner = new FakeProcessRunner();
        runner.ExitCodeWhenArgumentsContain["sln"] = 1;

        var result = Add(app, runner, "cleanup", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: dotnet sln add failed — see its output above."), result.Error);
        Assert.Equal(string.Empty, result.Output);   // the engine never ran
        Assert.Single(runner.Calls);
        Assert.False(Directory.Exists(ProjectDir(app, "Shop.CleanupWorker")));
        Assert.Equal(appHostBefore, app.Read(app.AppHost));
        Assert.Equal(appHostProjectBefore, app.Read(app.AppHostProject));
    }

    [Fact]
    public void A_red_validate_skips_drift_and_reports_the_rollback()
    {
        using var app = new FakeApp();
        var runner = new FakeProcessRunner();
        runner.ExitCodeWhenArgumentsContain["validate"] = 1;

        var result = Add(app, runner, "cleanup", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Equal(Line("goldpath: worker 'Shop.CleanupWorker' (schedule) wired — running the engine (specdrift validate + drift)"), result.Output);
        Assert.Equal(Line("goldpath: the engine rejected the result — ALL files restored; fix the findings above and retry (the worker was NOT added)."), result.Error);
        Assert.DoesNotContain(runner.Calls, c => c.Arguments.Contains("drift"));
    }

    [Fact]
    public void A_red_drift_after_a_green_validate_still_restores()
    {
        using var app = new FakeApp();
        var appHostBefore = app.Read(app.AppHost);
        var runner = new FakeProcessRunner();
        runner.ExitCodeWhenArgumentsContain["--repo"] = 1;   // `drift --repo .` (validate's `.specdrift/rules.yaml` would match "drift")

        var result = Add(app, runner, "cleanup", "schedule");
        Assert.Equal(1, result.Code);
        Assert.Contains(runner.Calls, c => c.Arguments.Contains("--repo"));   // drift DID run
        Assert.False(Directory.Exists(ProjectDir(app, "Shop.CleanupWorker")));
        Assert.Equal(appHostBefore, app.Read(app.AppHost));
        Assert.DoesNotContain("engine clean", result.Output, StringComparison.Ordinal);
    }

    // ── the success story: exact console, exact AppHost, exact project ─────────────────

    [Fact]
    public void Queue_success_prints_the_queue_decisions()
    {
        using var app = new FakeApp(messagingWired: true);
        var result = Add(app, new FakeProcessRunner(), "payments", "queue");
        Assert.Equal(0, result.Code);
        Assert.Equal(string.Empty, result.Error);
        Assert.Equal(
            Line("goldpath: worker 'Shop.PaymentsWorker' (queue) wired — running the engine (specdrift validate + drift)")
            + Line("goldpath: worker 'Shop.PaymentsWorker' added as resource 'payments-worker' — engine clean. Your decisions (goldpath never guesses domain opt-ins):")
            + Line("  → rename WorkItemQueued to the REAL upstream event (broker-bound contracts implement IIntegrationEvent — GP0401)")
            + Line("  → consuming an event the API publishes? the record moves to a shared <App>.Contracts classlib referenced by BOTH — events are wire contracts, never duplicated (docs/rfc/goldpath-event-contracts.md)")
            + Line("  → put the real work into the consumer; it commits WITH the inbox bookkeeping — exactly-once by construction")
            + Line("  → the worker owns its OWN tables' migrations: run `goldpath db add add-worker` and commit the migration"),
            result.Output);
    }

    [Fact]
    public void Schedule_success_prints_the_schedule_decisions()
    {
        using var app = new FakeApp();
        var result = Add(app, new FakeProcessRunner(), "cleanup", "schedule");
        Assert.Equal(0, result.Code);
        Assert.Equal(
            Line("goldpath: worker 'Shop.CleanupWorker' (schedule) wired — running the engine (specdrift validate + drift)")
            + Line("goldpath: worker 'Shop.CleanupWorker' added as resource 'cleanup-worker' — engine clean. Your decisions (goldpath never guesses domain opt-ins):")
            + Line("  → put the real work into IntervalJob.RunTickAsync (time-abstracted, directly testable); configure Worker:Interval")
            + Line("  → when the work outgrows a timer (chunks, resume, SLA), move to --trigger jobs — the Jobs module is the landing pad"),
            result.Output);
    }

    [Fact]
    public void Jobs_success_prints_the_jobs_decisions()
    {
        using var app = new FakeApp();
        var result = Add(app, new FakeProcessRunner(), "eod-report", "jobs");
        Assert.Equal(0, result.Code);
        Assert.Equal(
            Line("goldpath: worker 'Shop.EodReportWorker' (jobs) wired — running the engine (specdrift validate + drift)")
            + Line("goldpath: worker 'Shop.EodReportWorker' added as resource 'eod-report-worker' — engine clean. Your decisions (goldpath never guesses domain opt-ins):")
            + Line("  → replace NightlyReportJob's body with the real aggregation; review the cron and the Deadline (every job has an SLA — GP1302)")
            + Line("  → the worker runs its OWN fleet (SchedulerName) against the app database — the Api's scheduler is untouched; both consoles ride MapGoldpathJobsAdmin")
            + Line("  → the shared jobs tables stay the API context's migrations (the D3 exclusion is generated); run `goldpath db add add-worker` for the worker's PRIVATE tables"),
            result.Output);
    }

    private const string AppHostHead = """
        var builder = DistributedApplication.CreateBuilder(args);

        var database = builder.AddPostgres("dbserver").AddDatabase("shopdb");
        // goldpath:features resources — the drift profile is the source of these rows

        builder.AddProject<Projects.Shop_Api>("api")
            .WithReference(database).WaitFor(database)
            // goldpath:features references — the drift profile is the source of these rows
            .WithHttpHealthCheck("/health/ready");

        // goldpath:workers — additional worker projects wire here (goldpath add worker)


        """;   // the wiring block opens with an empty line — two newlines after the anchor

    private const string AppHostTail = """

        builder.Build().Run();
        """;

    [Fact]
    public void Queue_apphost_chains_database_then_messaging_then_probe()
    {
        using var app = new FakeApp(messagingWired: true);
        Assert.Equal(0, Add(app, new FakeProcessRunner(), "payments", "queue").Code);
        Assert.Equal(
            AppHostHead
            + "builder.AddProject<Projects.Shop_PaymentsWorker>(\"payments-worker\")\n"
            + "    .WithReference(database).WaitFor(database)\n"
            + "    .WithReference(messaging).WaitFor(messaging)\n"
            + "    .WithHttpHealthCheck(\"/health/ready\");\n"
            + AppHostTail,
            Normalize(app.Read(app.AppHost)));
    }

