    // ── the skeleton, byte for byte ────────────────────────────────────────────────────

    private static void AssertProjectIsExactly(string projectDir, IReadOnlyDictionary<string, string> expected)
    {
        var actual = Directory.EnumerateFiles(projectDir, "*", SearchOption.AllDirectories)
            .ToDictionary(path => Path.GetRelativePath(projectDir, path).Replace('\\', '/'), path => Normalize(File.ReadAllText(path)), StringComparer.Ordinal);
        Assert.Equal(expected.Keys.Order(StringComparer.Ordinal), actual.Keys.Order(StringComparer.Ordinal));
        foreach (var (file, content) in expected)
        {
            Assert.True(content == actual[file], $"{file} differs from the golden skeleton");
        }
    }

